using System.Globalization;

namespace ChromieLauncher.Core;

/// <summary>Launcher-owned text only; addon metadata and technical diagnostics are not translated.</summary>
public static class LauncherText
{
    public static string Language { get; private set; } = "en";
    private static CultureInfo Culture => CultureInfo.GetCultureInfo(Language switch { "fr" => "fr-FR", "it" => "it-IT", _ => "en-US" });

    public static string NormalizeLanguage(string? language) => language is "fr" or "it" ? language : "en";

    public static void SetLanguage(string? language)
    {
        Language = NormalizeLanguage(language);
        var culture = Culture;
        CultureInfo.DefaultThreadCurrentCulture = CultureInfo.CurrentCulture = culture;
        CultureInfo.DefaultThreadCurrentUICulture = CultureInfo.CurrentUICulture = culture;
    }

    public static string Get(string text, string? language = null)
    {
        var code = NormalizeLanguage(language ?? Language);
        return code != "en" && Translations.TryGetValue(text, out var value) ? code == "fr" ? value.Fr : value.It : text;
    }

    public static string Format(string text, params object[] arguments) => string.Format(Culture, Get(text), arguments);

